const TEST=`const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');const ROOT=path.resolve(__dirname,'..'),read=r=>JSON.parse(fs.readFileSync(path.join(ROOT,r),'utf8'));const KEY='${KEY}',ROLE='${ROLE}',MODEL='${MODEL}',GRAMMAR='${GRAMMAR}',PLAN='${PLAN}',TYPES=${JSON.stringify(TYPES)},ACTORS=${JSON.stringify(ACTORS)},PLACES=${JSON.stringify(PLACES)};const g=read(GRAMMAR);assert.equal(g.persistent_work_object_contract.id,'programportefolje_og_beslutningslogg');assert.match(g.rhythm_contract.loop,/waiting|venting/i);assert.deepEqual(g.actor_grammar.map(x=>x.id),ACTORS);assert.deepEqual(g.place_grammar.map(x=>x.id),PLACES);assert.ok(g.knowledge_dependencies.some(x=>x.id==='history_go_scenekunst_inger_buresund_black_box_programmering'));assert.deepEqual(g.mail_generation_contract.required_mail_types,TYPES);assert.equal(g.day_one_contract.entry,'appointment_required');assert.match(g.authority_boundary.may_not.join(' '),/habilit/);assert.match(g.authority_boundary.may_not.join(' '),/rettighet/);assert.match(g.authority_boundary.may_not.join(' '),/teknisk/);assert.equal(read('data/Civication/roleModels/manifest.json').files.filter(x=>x===MODEL).length,1);const model=read(MODEL);assert.deepEqual(model.work_life.workplaces,PLACES);assert.deepEqual(model.related_people.map(x=>x.id),ACTORS);for(const [i,p] of model.related_people.entries()){assert.equal(p.fictional,true);assert.equal(p.fictional_scenario_actor,true);assert.equal(p.canonical_person_ref,null);assert.deepEqual(p.workplace_ids,[PLACES[i]]);assert.ok(p.function.length>=220);assert.ok(p.authority_relation.length>=220)}assert.ok(model.career_path.possible_promotions.length>=2);assert.ok(model.career_path.possible_exits.length>=2);assert.ok(model.required_knowledge.history_go_badges.includes('scenekunst'));const plan=read(PLAN);assert.equal(plan.id,ROLE+'_foundation_v1');assert.equal(plan.sequence.length,16);assert.deepEqual(plan.sequence.map(x=>x.type),['job','people','knowledge','job','people','conflict','job','people','event','micro','job','people','followup','story','consequence','job']);for(const [i,s] of plan.sequence.entries()){assert.equal(s.step,i+1);assert.deepEqual(s.fallback_types,[]);assert.equal(s.allowed_families.length,1)}for(const x of ['promoted','fired','stagnated'])assert.ok(plan.outcome_rules[x]);const counts={job:4,people:4,conflict:1,story:1,event:1,micro:1,followup:1,knowledge:1,consequence:1},ids=new Set(),subjects=new Set();for(const type of TYPES){const c=read('data/Civication/mailFamilies/scenekunst/'+type+'/'+ROLE+'_'+type+'.json'),m=c.families.flatMap(f=>f.mails||[]);assert.equal(c.schema,'civication_mail_family_catalog_v1');assert.equal(c.mail_type,type);assert.equal(m.length,counts[type]);for(const x of m){assert.ok(!ids.has(x.id));assert.ok(!subjects.has(x.subject));ids.add(x.id);subjects.add(x.subject);assert.ok(x.summary.length>=320);assert.equal(x.situation.length,3);assert.equal(x.choices.length,2);for(const q of x.choices){assert.ok(q.reply.length>=150);assert.ok(q.feedback.length>=220);assert.ok(Object.keys(q.effects.stats).length>=3)}}}assert.equal(ids.size,15);const k=read('data/Civication/mailFamilies/scenekunst/knowledge/'+ROLE+'_knowledge.json').families[0].mails[0];assert.equal(k.place_id,'black_box_teater');assert.equal(k.task_payload.person_id,'inger_buresund');assert.equal(k.task_contract.completion_rule,'history_go_payload_completed');for(const r of k.task_contract.evidence_refs)assert.ok(fs.existsSync(path.join(ROOT,r)),r);const pack=read('data/Civication/rolePackIndex.json').roles.find(x=>x.category==='scenekunst'&&x.role_scope===ROLE);assert.equal(pack.status,'complete_reference_v2');const career=read('data/Civication/careerGameplayMatrix.json').worlds.find(x=>x.key===KEY);assert.equal(career.status,'playable');assert.equal(career.audit.runtime_gate,true);assert.deepEqual(career.audit.missing_components,[]);const rr=read('data/Civication/roleWorldRolloutReadiness.json'),ready=rr.roles.find(x=>x.key===KEY);assert.equal(ready.classification,'rollout_ready');assert.ok(['role_world_not_started','role_world_complete'].includes(ready.role_world_status));for(const d of ['people_places_integrity','persistent_work_object','rhythm_waiting_handoff_rework','history_go_affordance','situated_reputation'])assert.equal(ready.dimensions[d].status,'foundation_ready',d);assert.deepEqual(ready.authored_work_required,[]);assert.equal(ready.cross_role.need,'not_required_for_rollout');assert.equal(rr.rollout_queue.some(x=>x.key===KEY),ready.role_world_status==='role_world_not_started');assert.equal(rr.gate.gate_pass,true);const sp=read('data/Civication/scenarioPeople/generated/scenekunst.json'),fp=new Set(Object.values(sp.people_pool||{}).flat().map(x=>x.person_id));for(const id of ACTORS)assert.ok(!fp.has(id));const sf=fs.readFileSync(path.join(ROOT,'reports/CIVICATION_SCENEKUNST_PROGRAM_OG_KURATERING_PREREQUISITES_SOURCE_FIRST.md'),'utf8');assert.match(sf,/not Role World completion/i);assert.match(sf,/programportefolje_og_beslutningslogg/);assert.match(sf,/not_required_for_rollout/);assert.match(sf,/29\\/30/);console.log('Civication Scenekunst Program og kuratering prerequisites: OK');`;
